          opacity: enabled ? 1 : .5,
          child: DefaultTextStyle.merge(
            style: t.text.sm.copyWith(color: c.mutedForeground),
            child: description!,
          ),
        ),
      if (error != null)
        DefaultTextStyle.merge(
          style: t.text.sm.copyWith(color: c.destructive),
          child: error!,
