    Widget beside() => Row(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Expanded(
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              ?label,
              for (final n in notes) ...[const SizedBox(height: 6), n],
            ],
