    required this.onPressed,
    required this.role,
    this.leading,
    this.trailing,
    this.shortcut,
    this.destructive = false,
    this.selected,
    this.checked,
    this.expanded,
    this.indicator,
    this.inset = false,
    this.autofocus = false,
    this.closeOnPress = true,
    this.lit = false,
    this.focusNode,
    this.onHover,
    this.keys = const {},
  });

  final Widget child;
  final VoidCallback? onPressed;
  final SemanticsRole role;
  final Widget? leading, trailing, shortcut, indicator;
  final bool destructive, inset, autofocus, closeOnPress, lit;
  final bool? selected, checked, expanded;
  final FocusNode? focusNode;
  final VoidCallback? onHover;
  final Map<ShortcutActivator, VoidCallback> keys;

  @override
  State<_MenuRow> createState() => _MenuRowState();
}

class _MenuRowState extends State<_MenuRow> {
  FocusNode? _own;
  FocusNode get _focus => widget.focusNode ?? (_own ??= FocusNode());

  @override
  void dispose() {
    _own?.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final t = AshlarTheme.of(context);
    final c = t.colors;
    final menu = MenuController.maybeOf(context);
    return MouseRegion(
      // The pointer and the keyboard share one highlight, as in a native menu; moving to
      // another row closes a submenu left open beside this menu.
      onEnter: (_) {
        if (widget.onPressed == null) return;
        _focus.requestFocus();
        if (widget.onHover != null) {
          widget.onHover!();
        } else {
          menu?.closeChildren();
        }
      },
      child: Focus(
        canRequestFocus: false,
        skipTraversal: true,
        onFocusChange: (_) => setState(() {}),
        child: CallbackShortcuts(
          bindings: widget.keys,
          child: Pressable(
            focusNode: _focus,
            autofocus: widget.autofocus,
            role: widget.role,
            selected: widget.selected,
            checked: widget.checked,
            expanded: widget.expanded,
            onPressed: widget.onPressed == null
                ? null
                : () {
                    if (widget.closeOnPress) {
                      (_MenuRoot.of(context) ?? menu)?.close();
                    }
                    widget.onPressed!();
                  },
            builder: (context, state) {
              final lit =
                  state.enabled &&
                  (widget.lit || state.hovered || _focus.hasFocus);
              final fg = widget.destructive
                  ? c.destructive
                  : (lit ? c.accentForeground : c.popoverForeground);
              final bg = lit
                  ? (widget.destructive
                        ? c.destructive.withValues(alpha: .1)
                        : c.accent)
                  : const Color(0x00000000);
              return Opacity(
                opacity: state.enabled ? 1 : .5,
                child: Container(
                  padding: EdgeInsetsDirectional.only(
                    start: widget.inset ? 32 : 8,
                    end: 8,
                    top: 6,
                    bottom: 6,
                  ),
                  decoration: BoxDecoration(
                    color: bg,
                    borderRadius: BorderRadius.circular(t.radiusSm),
                  ),
                  child: DefaultTextStyle.merge(
                    style: t.text.sm.copyWith(color: fg),
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    child: IconTheme.merge(
                      data: IconThemeData(
                        color: widget.destructive
                            ? c.destructive
                            : c.mutedForeground,
                        size: 16,
                      ),
                      child: Stack(
                        clipBehavior: Clip.none,
                        alignment: AlignmentDirectional.centerStart,
                        children: [
                          // Checks and dots sit in the inset, in the item's own colour.
                          if (widget.indicator != null)
                            PositionedDirectional(
                              start: -24,
                              child: SizedBox(
                                width: 16,
                                child: Center(
                                  child: IconTheme.merge(
                                    data: IconThemeData(color: fg),
                                    child: widget.indicator!,
                                  ),
                                ),
                              ),
                            ),
                          Row(
                            children: [
                              if (widget.leading != null) ...[
                                widget.leading!,
                                const SizedBox(width: 8),
                              ],
                              Expanded(child: widget.child),
                              if (widget.shortcut != null) ...[
                                const SizedBox(width: 16),
                                DefaultTextStyle.merge(
                                  style: t.text.xs.copyWith(
                                    color: c.mutedForeground,
                                    letterSpacing: 1.2,
                                  ),
                                  child: widget.shortcut!,
                                ),
                              ],
                              if (widget.trailing != null) ...[
                                const SizedBox(width: 8),
                                widget.trailing!,
                              ],
                            ],
                          ),
                        ],
                      ),
                    ),
                  ),
                ),
              );
            },
          ),
        ),
      ),
    );
  }
}

