                      child: chosen
                          ? AshlarIcon(
                              AshlarIconsRoundedStroke.check,
                              size: 16,
                              color: fg,
                            )
                          : null,
                    ),
                  ],
                ),
              ),
            ),
          ),
        ),
      ),
    );
  }
}
