/// ])
/// ```
class Accordion extends StatefulWidget {
  const Accordion({
    super.key,
    required this.items,
    this.multiple = false,
    this.initiallyOpen = const {},
    this.bordered = false,
  });

  final List<AccordionItem> items;
  final bool multiple;

  /// The sections open at first, by index.
