              child: SafeArea(
                top: side != DrawerSide.bottom,
                bottom: side != DrawerSide.top,
                child: Semantics(
                  scopesRoute: true,
                  namesRoute: true,
                  explicitChildNodes: true,
                  child: DefaultTextStyle(
                    style: t.text.sm.copyWith(color: c.foreground),
                    child: vertical
                        ? Column(
