                            children: [
                              // The handle: a reminder it can be dragged, not a control.
                              if (side == DrawerSide.bottom) handle,
                              Flexible(
                                child: ConstrainedBox(
                                  constraints: BoxConstraints(
                                    maxWidth: widget.maxWidth,
                                  ),
                                  child: body,
                                ),
                              ),
                              if (side == DrawerSide.top) handle,
                            ],
                          )
                        : body,
                  ),
                ),
              ),
            ),
          );
        },
      ),
    );
  }
}
