/// A small button at the end of an item or a group's label: "more", "add".
@immutable
class SidebarAction {
  const SidebarAction({
    required this.icon,
    required this.label,
    required this.onPressed,
  });

  final IconData icon;

  /// What it does, for screen readers and its tooltip.
