/// A place in the app, on the sidebar. With [children] it opens a list of its own.
@immutable
class SidebarItem {
  const SidebarItem(
    this.label, {
    required this.icon,
    this.onPressed,
    this.active = false,
    this.badge,
    this.action,
    this.children = const [],
    this.initiallyOpen = false,
