                  items: [
                    for (final (v, l) in _ranges) ToggleGroupItem(v, Text(l)),
                  ],
                ),
        ),
        CardContent(
          child: AreaChart(
            semanticLabel: 'Visitors by day',
            stacked: true,
            labels: [for (final d in days) '${_months[d.month - 1]} ${d.day}'],
            series: [
              ChartSeries('Desktop', [
                for (final d in days) sum(_desktop, d).toDouble(),
