                  error ? AshlarIconsRoundedStroke.circleAlert : icon,
                  size: upright ? 24 : (size == AttachmentSize.xs ? 14 : 16),
                  color: error ? c.destructive : c.foreground,
                ),
              ),
            if (busy)
